/*
 * Ride log as an A5 photo book — shared by every post. Reads the post's plain
 * content (.source, generated by tools/sync-ride.py), cuts it into A5 pages and
 * binds them into leaves you flip: two-page spreads on a wide screen, one page
 * at a time on a phone. Click/tap a page, swipe, or use the arrow keys.
 *
 * Pages, in order: cover · inside cover (blank) · title · the story · back cover.
 * The story keeps Notion's order: every photo gets a page to itself (a tall one
 * full-bleed, a wide one edge to edge), and the words that follow it flow onto
 * the next page(s). A photo (or the first of a run of photos) always starts on
 * a left-hand page, so it faces its words across the spread — a blank page
 * goes in when it would land on the right (before a one-page passage, so the
 * words sit on the right-hand page). A passage that fits on one page sits
 * centred on it.
 */
(() => {
  const src = document.querySelector('.source')
  if (!src) return

  const el = (tag, cls, parent) => {
    const e = document.createElement(tag)
    if (cls) e.className = cls
    if (parent) parent.append(e)
    return e
  }
  const bodyOf = (page) => page.querySelector('.page__body')
  const makePage = (kind) => {
    const p = el('div', 'page page--' + kind)
    el('div', 'page__body', p)
    return p
  }
  const cloneKids = (sel) => [...src.querySelector(sel).childNodes].map((n) => n.cloneNode(true))

  /** Cut the post into pages (at a fixed measuring size — everything is in
   *  A5 millimetres, so the breaks are the same at any size). */
  function paginate() {
    const measure = el('div', 'measure', document.body)
    const pages = []
    const add = (kind) => {
      const p = makePage(kind)
      measure.append(p)
      pages.push(p)
      return p
    }
    const over = (p) => {
      const b = bodyOf(p)
      return b.scrollHeight > b.clientHeight + 1
    }

    bodyOf(add('cover')).append(...cloneKids('.src-cover'))
    add('blank')
    bodyOf(add('title')).append(...cloneKids('.src-title'))

    let cur = null // the text page being filled
    let run = [] // the text pages of the current passage
    let lastRun = []
    const endRun = () => {
      if (run.length === 1 && !run[0].querySelector('h2')) run[0].classList.add('is-centered')
      if (run.length) lastRun = run
      run = []
      cur = null
    }
    const textPage = () => {
      cur = add('text')
      run.push(cur)
      return cur
    }

    let prevPhoto = false
    for (const block of src.querySelector('.src-flow').children) {
      const isPhoto = block.tagName === 'FIGURE'
      const afterPhoto = prevPhoto
      prevPhoto = isPhoto
      if (isPhoto) {
        endRun()
        // Left-hand pages are the odd ones (the cover, page 0, is on the right).
        // A one-page passage just before moves across to the right-hand page,
        // facing the blank, rather than leaving the blank on the right.
        if (!afterPhoto && pages.length % 2 === 0) {
          if (lastRun.length === 1 && pages.at(-1) === lastRun[0]) pages.splice(-1, 0, makePage('blank'))
          else add('blank')
        }
        const p = add('photo')
        p.classList.add(block.classList.contains('photo--tall') ? 'is-tall' : 'is-wide')
        bodyOf(p).append(block.cloneNode(true))
        continue
      }
      if (block.tagName === 'H2') {
        textPage()
        bodyOf(cur).append(block.cloneNode(true))
        continue
      }
      if (!cur) textPage()
      // A paragraph: fill the page, carry the rest over word by word.
      let words = block.textContent.trim().split(/\s+/)
      while (words.length) {
        const para = el('p', null, bodyOf(cur))
        para.textContent = words.join(' ')
        if (!over(cur)) break
        let lo = 0
        let hi = words.length - 1
        while (lo < hi) {
          const mid = Math.ceil((lo + hi) / 2)
          para.textContent = words.slice(0, mid).join(' ')
          if (over(cur)) hi = mid - 1
          else lo = mid
        }
        if (lo === 0) {
          if (bodyOf(cur).children.length === 1) break // not even a word fits an empty page; leave it
          para.remove()
        } else {
          para.textContent = words.slice(0, lo).join(' ')
          words = words.slice(lo)
        }
        textPage()
      }
    }
    endRun()
    bodyOf(add('back')).append(...cloneKids('.src-back'))

    pages.forEach((p, i) => {
      if (p.classList.contains('page--text')) el('div', 'page__folio', p).textContent = i
    })
    measure.remove()
    return pages
  }

  function start(pages) {
    // Print: every page in order, one A5 sheet each.
    const flow = el('div', 'print-flow', document.body)
    for (const p of pages) flow.append(p.cloneNode(true))

    const stage = el('div', 'stage', document.body)
    const book = el('div', 'book', stage)
    const icon = (d) => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${d}"/></svg>`
    const close = el('a', 'book-close', document.body)
    close.href = '/blog/index.html'
    close.setAttribute('aria-label', 'Back to the ride logs')
    close.innerHTML = icon('M6 6l12 12M18 6L6 18')
    const prevBtn = el('button', 'book-nav book-nav--prev', document.body)
    prevBtn.setAttribute('aria-label', 'Previous page')
    prevBtn.innerHTML = icon('M15 5l-7 7 7 7')
    const nextBtn = el('button', 'book-nav book-nav--next', document.body)
    nextBtn.setAttribute('aria-label', 'Next page')
    nextBtn.innerHTML = icon('M9 5l7 7-7 7')

    let spread = null
    let seq = [] // pages in binding order for the current mode
    let leaves = []
    let at = 0 // leaves turned

    // The page being read: the left page of a spread, else the one showing.
    const reading = () => (spread ? seq[Math.max(0, at * 2 - 1)] : seq[at])
    const last = () => (spread ? leaves.length : leaves.length - 1)

    function bind(isSpread, keep) {
      spread = isSpread
      // Spreads keep the blank inside cover and need an even count (so the back
      // cover is the back of the last leaf); one-up skips blanks.
      seq = spread ? pages.slice() : pages.filter((p) => !p.classList.contains('page--blank'))
      if (spread && seq.length % 2) seq.splice(seq.length - 1, 0, makePage('blank'))
      book.classList.add('no-anim')
      book.classList.toggle('is-single', !spread)
      book.replaceChildren()
      leaves = []
      const per = spread ? 2 : 1
      for (let i = 0; i < seq.length; i += per) {
        const leaf = el('div', 'leaf', book)
        el('div', 'face face--front', leaf).append(seq[i])
        const back = el('div', 'face face--back', leaf)
        if (spread && seq[i + 1]) back.append(seq[i + 1])
        leaves.push(leaf)
      }
      const idx = Math.max(0, seq.indexOf(keep))
      at = Math.min(last(), spread ? Math.ceil(idx / 2) : idx)
      render()
      requestAnimationFrame(() => requestAnimationFrame(() => book.classList.remove('no-anim')))
    }

    function render(moving) {
      const n = leaves.length
      leaves.forEach((leaf, i) => {
        leaf.classList.toggle('is-flipped', i < at)
        if (leaf !== moving) leaf.style.zIndex = i < at ? i + 1 : n - i + 1
      })
      // A closed book sits centred: the front cover alone, or the back cover alone.
      const shift = !spread ? 0 : at === 0 ? -0.5 : at === n ? 0.5 : 0
      book.style.transform = `translateX(calc(var(--pw) * ${shift}))`
      prevBtn.disabled = at === 0
      nextBtn.disabled = at === last()
      const i = pages.indexOf(reading())
      history.replaceState(null, '', i > 0 ? '#' + i : location.pathname)
    }

    function go(to) {
      to = Math.max(0, Math.min(last(), to))
      if (to === at) return
      const moving = leaves[Math.min(at, to)]
      at = to
      moving.style.zIndex = leaves.length + 5 // over both stacks while it turns
      clearTimeout(moving.settle)
      moving.settle = setTimeout(() => render(), 950)
      render(moving)
    }

    function layout() {
      const vw = innerWidth
      const vh = innerHeight
      const wide = vw >= 720 && vw / vh > 0.95
      const padX = wide ? 88 : 16
      const padTop = wide ? 48 : 72
      const padBottom = wide ? 48 : 80
      let ph = vh - padTop - padBottom
      let pw = (ph * 148) / 210
      const maxW = (vw - padX * 2) / (wide ? 2 : 1)
      if (pw > maxW) {
        pw = maxW
        ph = (pw * 210) / 148
      }
      book.style.setProperty('--pw', pw + 'px')
      book.style.setProperty('--ph', ph + 'px')
      if (wide !== spread) bind(wide, spread === null ? pages[+location.hash.slice(1)] : reading())
    }

    addEventListener('resize', layout)
    layout()
    requestAnimationFrame(() => stage.classList.add('is-ready'))

    prevBtn.addEventListener('click', () => go(at - 1))
    nextBtn.addEventListener('click', () => go(at + 1))
    addEventListener('keydown', (e) => {
      if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') go(at + 1)
      else if (e.key === 'ArrowLeft' || e.key === 'PageUp') go(at - 1)
      else if (e.key === 'Escape') location.href = close.href
      else return
      e.preventDefault()
    })

    // Tap/click the right-hand side to turn forward, the left to turn back; or swipe.
    let down = null
    stage.addEventListener('pointerdown', (e) => {
      down = e.target.closest('a') ? null : { x: e.clientX, y: e.clientY }
    })
    stage.addEventListener('pointerup', (e) => {
      if (!down) return
      const dx = e.clientX - down.x
      const dy = e.clientY - down.y
      down = null
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) return go(at + (dx < 0 ? 1 : -1))
      if (Math.abs(dx) > 8 || Math.abs(dy) > 8) return
      const r = book.getBoundingClientRect()
      const split = spread ? r.left + r.width / 2 : r.left + r.width * 0.3
      go(at + (e.clientX >= split ? 1 : -1))
    })
  }

  const fonts = ['300 16px Newsreader', '16px Newsreader', 'italic 16px Newsreader', '500 16px Montserrat']
  Promise.all(fonts.map((f) => document.fonts.load(f).catch(() => null)))
    .then(() => start(paginate()))
})()
